import { CONFIG_NAMES, type ConfigName, LEVELS, type RuleSetting } from "./configs/index";
import type { ShadowRule } from "./rule";
import { rules } from "./rules/index";

/** A generated documentation file: a path relative to the package and its text. */
export interface DocFile {
  path: string;
  content: string;
}

const GENERATED =
  "<!-- Generated by scripts/generate-docs.mjs from the rule's meta. Do not edit. -->";

function settingText(setting: RuleSetting): string {
  if (typeof setting === "string") return setting;
  return `${setting[0]} (${JSON.stringify(setting[1])})`;
}

function fence(code: string): string {
  return `\`\`\`tsx\n${code.trim()}\n\`\`\``;
}

function schemaText(rule: ShadowRule): string | null {
  const schema = rule.meta.schema;
  if (schema === undefined || schema === null) return null;
  if (Array.isArray(schema) && schema.length === 0) return null;
  return JSON.stringify(schema, null, 2);
}

/**
 * Renders the documentation page of one rule from its `meta`: description, rationale, examples,
 * options (the JSON schema), messages and the severity in every shipped config.
 *
 * @param name Rule name without the `shadow/` prefix.
 * @param rule The rule module.
 * @returns Markdown text.
 * @example
 * const markdown = renderRuleDoc("no-async-effect", rules["no-async-effect"]);
 * @since 1.0.0
 */
export function renderRuleDoc(name: string, rule: ShadowRule): string {
  const { docs } = rule.meta;
  const messages = rule.meta.messages ?? {};
  const badges: string[] = [];
  if (docs.recommended) badges.push("recommended");
  if (rule.meta.fixable !== undefined) badges.push("fixable");
  if (rule.meta.hasSuggestions === true) badges.push("has suggestions");
  if (docs.typeAware === true) badges.push("uses types when available");
  const lines: string[] = [
    GENERATED,
    "",
    `# shadow/${name}`,
    "",
    docs.description,
    "",
    badges.length > 0 ? badges.map((badge) => `\`${badge}\``).join(" ") : "",
    "",
    "## Why",
    "",
    docs.rationale,
    "",
    "## Incorrect",
    "",
    ...docs.examples.incorrect.flatMap((example) => [fence(example), ""]),
    "## Correct",
    "",
    ...docs.examples.correct.flatMap((example) => [fence(example), ""]),
  ];
  const schema = schemaText(rule);
  if (schema !== null) {
    lines.push("## Options", "", "```json", schema, "```", "");
    const defaults = rule.meta.defaultOptions;
    if (defaults !== undefined) {
      lines.push(`Defaults: \`${JSON.stringify(defaults)}\``, "");
    }
  }
  if (rule.meta.fixable !== undefined || rule.meta.hasSuggestions === true) {
    const fixes = rule.meta.fixable !== undefined;
    const suggests = rule.meta.hasSuggestions === true;
    lines.push(
      `## ${fixes && suggests ? "Autofix and suggestions" : fixes ? "Autofix" : "Suggestions"}`,
      "",
      docs.fix ?? "",
      "",
    );
  }
  lines.push(
    "## Disabling",
    "",
    `Disable one line with \`// eslint-disable-next-line shadow/${name}\`, a block with \`/* eslint-disable shadow/${name} */\` and \`/* eslint-enable shadow/${name} */\`, or a whole file with the block form at its top. ${docs.disableWhen}`,
    "",
  );
  if (docs.notes !== undefined && docs.notes.length > 0) {
    lines.push("## Notes", "", ...docs.notes.map((note) => `- ${note}`), "");
  }
  lines.push(
    "## Messages",
    "",
    ...Object.entries(messages).map(([id, text]) => `- \`${id}\`: ${text}`),
    "",
    "## Configs",
    "",
    "| Config | Setting |",
    "| --- | --- |",
    ...CONFIG_NAMES.map((config) => {
      const setting = LEVELS[name]?.[config];
      return `| \`${config}\` | ${setting === undefined ? "off" : settingText(setting)} |`;
    }),
    "",
    "## Tests",
    "",
    `Invariant \`${docs.id}\` (\`test/rules/${name}.test.ts\`).`,
    "",
  );
  return `${lines.join("\n").replace(/\n{3,}/g, "\n\n")}`;
}

/** The rule index page: one row per rule with its id, kind and severity per config. */
export function renderIndex(): string {
  const rows = Object.entries(rules).map(([name, rule]) => {
    const { docs } = rule.meta;
    const levels = CONFIG_NAMES.map((config: ConfigName) => {
      const setting = LEVELS[name]?.[config];
      return setting === undefined ? "off" : typeof setting === "string" ? setting : setting[0];
    });
    const fixes = [
      rule.meta.fixable !== undefined ? "fix" : "",
      rule.meta.hasSuggestions === true ? "suggestions" : "",
    ]
      .filter((value) => value !== "")
      .join(", ");
    return `| [\`shadow/${name}\`](./${name}.md) | ${docs.id} | ${docs.description} | ${fixes} | ${levels.join(" | ")} |`;
  });
  return [
    GENERATED,
    "",
    "# Rules",
    "",
    `| Rule | Id | Description | Fixes | ${CONFIG_NAMES.join(" | ")} |`,
    `| --- | --- | --- | --- | ${CONFIG_NAMES.map(() => "---").join(" | ")} |`,
    ...rows,
    "",
  ].join("\n");
}

/**
 * All generated documentation files (`docs/rules/<name>.md` and the index). The generator script
 * writes them; a test fails when they differ from the files on disk.
 *
 * @returns One entry per file.
 * @since 1.0.0
 */
export function renderAllDocs(): DocFile[] {
  const files: DocFile[] = Object.entries(rules).map(([name, rule]) => ({
    path: `docs/rules/${name}.md`,
    content: renderRuleDoc(name, rule),
  }));
  files.push({ path: "docs/rules/README.md", content: renderIndex() });
  return files;
}
